"""Synthetic order-desk client — after the approved repair.

This file is invented for the demo. The change is the one the repair proposal describes: a stream that ends without
`[DONE]` raises `IncompleteMessage` instead of looking like a finished message, so nothing downstream acts on a tool call
whose result was never received.
"""
from __future__ import annotations


class IncompleteMessage(Exception):
    """The assistant message ended before the provider said it was finished."""


def read_stream(lines: list[str]) -> tuple[str, dict]:
    """Fold SSE lines into (text, tool_call). A message without `[DONE]` is refused, not returned."""
    text = ""
    tool_call: dict = {}
    for line in lines:
        if not line.startswith("data:"):
            continue
        body = line[5:].strip()
        if body == "[DONE]":
            return text, tool_call
        text += body
    raise IncompleteMessage("the stream ended without [DONE]; the assistant message is incomplete")


def next_action(tool_call: dict) -> str:
    """What the app does next. It is only reached for a message the provider actually finished."""
    if tool_call.get("name") == "lookup_order":
        return f"order-lookup:{tool_call.get('arguments', '{}')}"
    return "reply"
